app-document-home-alerts:
﻿@if (error()) {
  <div class="drive-alert drive-alert-error">
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
      <circle cx="12" cy="12" r="10" />
      <line x1="12" y1="8" x2="12" y2="12" />
      <line x1="12" y1="16" x2="12.01" y2="16" />
    </svg>
    {{ error() }}
    <ui-button type="button" class="alert-close" (click)="error.set(null)">×</ui-button>
  </div>
}
@if (success()) {
  <div class="drive-alert drive-alert-success">
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
      <polyline points="20 6 9 17 4 12" />
    </svg>
    {{ success() }}
    <ui-button type="button" class="alert-close" (click)="success.set(null)">×</ui-button>
  </div>
}
